package io.xeros.solo;
import io.xeros.*;import io.xeros.content.minigames.fight_cave.*;import io.xeros.content.combat.*;import io.xeros.content.combat.death.PlayerDeath;import io.xeros.model.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.npc.actions.NPCHitPlayer;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import java.util.*;
public final class FightCavesPlayableCheck {
 static void ok(boolean b,String s){BossesPlayableCheck.ok(b,s);}static Player actor(){Player p=BossRoutesCheck.actor();p.setLoginName("fight64qa");p.setDisplayName("Fight64qa");p.getHealth().setMaximumHealth(50000);p.getHealth().reset();return p;}static int count(Player p,int id){return p.getItems().getInventoryCount(id);}static void tick(Player p,int n){BossSpecialRoutesCheck.tick(p,n);}static List<NPC> living(Player p){List<NPC> list=new ArrayList<>();for(NPC n:NPCHandler.npcs)if(n!=null&&n.spawnedBy==p.getIndex()&&NPCHandler.isFightCaveNpc(n)&&!n.isDead()&&!n.isUnregister())list.add(n);return list;}static void clear(Player p){p.getFightCave().abandon();for(NPC n:new ArrayList<>(Arrays.asList(NPCHandler.npcs)))if(n!=null&&n.spawnedBy==p.getIndex()&&(NPCHandler.isFightCaveNpc(n)||n.getNpcId()==3128)&&n.isUnregister())n.processDeregistration();BossesPlayableCheck.clear(p);if(p.getIndex()!=1)PlayerHandler.players[p.getIndex()]=null;}
 static void kill(Player p,NPC n){n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);for(int i=0;i<40&&!n.needRespawn;i++)Server.npcHandler.getNpcProcess().process(n.getIndex());ok(n.needRespawn,"NPC corpse did not finish "+n.getNpcId());p.getFightCave().onNpcDeath(n);n.unregisterInstant();}
 static void complete(int type)throws Exception{Player p=actor();p.getFightCave().create(type);tick(p,16);int total=Wave.getWaveForType(p).length,kills=0;for(int wave=0;wave<total;wave++){ok(p.waveId==wave,"Wrong wave "+wave+" actual="+p.waveId);ok(!living(p).isEmpty(),"Empty/stuck wave "+wave);while(!living(p).isEmpty()){for(NPC n:living(p)){if(n.getNpcId()==Wave.TZTOK_JAD){n.getHealth().setCurrentHealth(120);tick(p,4);long healers=Arrays.stream(NPCHandler.npcs).filter(h->h!=null&&h.spawnedBy==p.getIndex()&&h.getNpcId()==3128&&!h.isUnregister()).count();ok(healers==4&&n.getHealth().getCurrentHealth()>120,"Jad healers did not spawn/heal");for(NPC h:NPCHandler.npcs)if(h!=null&&h.spawnedBy==p.getIndex()&&h.getNpcId()==3128&&!h.isUnregister()){h.underAttack=true;h.setPlayerAttackingIndex(p.getIndex());}int hp=n.getHealth().getCurrentHealth();tick(p,4);ok(n.getHealth().getCurrentHealth()==hp,"Aggro healers kept healing");}kill(p,n);kills++;if(p.fightCavesWaveType==0)break;}if(p.fightCavesWaveType==0)break;}
 if(wave<total-1)tick(p,16);}
 int capes=type==3?2:1;ok(count(p,6570)==capes&&p.waveInfo[type-1]==1&&p.waveId==0&&p.fightCavesWaveType==0&&count(p,6529)>=10000*type,"Completion reward/reset "+type);p.getFightCave().stop();p.getFightCave().reward();ok(count(p,6570)==capes&&p.waveInfo[type-1]==1,"Repeated reward "+type);ok(PlayerSave.saveGameInstant(p),"Reward save");Player q=actor();ok(PlayerSave.loadGame(q,"fight64qa","IsolatedAudit",true).toString().equals("SUCCESS")&&count(q,6570)==capes&&q.waveInfo[type-1]==1&&q.fightCavesWaveType==0&&q.getTeleportToX()==2438,"Fight reward persistence");PlayerHandler.players[1]=p;clear(p);clear(q);System.out.println("FIGHT_CAVES_FULL_"+total+"_WAVES_"+kills+"_REAL_NPC_DEATHS_SPLITS_JAD_FOUR_HEALERS_AGGRO_SINGLE_FIRE_CAPE_TOKKUL_AND_SAVE_RELOAD_PASS");}
 static void fullInventory(){Player p=actor();BossRoutesCheck.at(p,2400,5087,4);p.teleTimer=0;p.fightCavesWaveType=1;p.waveId=Wave.LEVEL_1.length-1;while(p.getItems().freeSlots()>0)ok(p.getItems().addItem(526,1),"Full bag fixture");p.getFightCave().spawn();tick(p,16);kill(p,living(p).get(0));ok(p.getItems().bankContains(6570)&&p.getItems().bankContains(6529)&&p.fightCavesWaveType==0,"Full bag lost Fire cape/Tokkul");clear(p);System.out.println("FIGHT_CAVES_FULL_INVENTORY_FIRE_CAPE_AND_TOKKUL_BANK_DELIVERY_PASS");}
 static void groundSafety(){Player p=actor();while(p.getItems().freeSlots()>0)ok(p.getItems().addItem(526,1),"Full bag fixture");for(io.xeros.model.items.bank.BankTab tab:p.getBank().getBankTab())for(int i=0;i<p.getBank().getBankCapacity();i++)tab.getItems().add(new io.xeros.model.items.bank.BankItem(527,1));io.xeros.content.bosses.nex.Nex arena=new io.xeros.content.bosses.nex.Nex(p,Boundary.Nex);arena.add(p);io.xeros.content.minigames.SoloActivityRewards.give(p,List.of(new io.xeros.model.items.GameItem(995,7)),FightCave.EXIT);io.xeros.model.items.GroundItem prize=Server.itemHandler.getGroundItem(null,995,2438,5168,0);ok(prize!=null&&prize.getAmount()==7&&prize.getInstance()==null,"Full bank reward trapped in disposed instance");arena.remove(p);ok(Server.itemHandler.getOwnedGroundItem(p,995,0)==prize,"World prize unavailable after disposal");Server.itemHandler.removeGroundItem(p,prize,false);clear(p);System.out.println("ACTIVITY_FULL_INVENTORY_FULL_BANK_REWARD_SURVIVES_ARENA_DISPOSAL_AS_PERSONAL_WORLD_DROP_PASS");}
 static void lifecycle(){Player p=actor();p.getFightCave().reward();p.getFightCave().stop();ok(count(p,6570)==0,"Unplayed reward");p.getFightCave().create(1);p.getFightCave().create(1);p.getFightCave().spawn();tick(p,16);ok(living(p).size()==Wave.LEVEL_1[0].length,"Duplicate start/spawn");p.getFightCave().leaveGame();tick(p,20);ok(living(p).isEmpty()&&p.fightCavesWaveType==0&&count(p,6570)==0,"Leave cleanup/reward");clear(p);p=actor();p.getFightCave().create(1);p.getFightCave().leaveGame();tick(p,20);ok(living(p).isEmpty(),"Pending spawn survived leave");clear(p);p=actor();p.getFightCave().create(1);tick(p,16);p.isDead=true;p.getHealth().setCurrentHealth(0);PlayerDeath.giveLife(p);tick(p,20);ok(p.getHealth().getCurrentHealth()>0&&!p.isDead&&p.fightCavesWaveType==0&&living(p).isEmpty()&&count(p,6570)==0,"Death cleanup/respawn");clear(p);for(int mode:new int[]{0,-1,4}){p=actor();p.getFightCave().create(mode);tick(p,20);ok(p.fightCavesWaveType==0&&living(p).isEmpty(),"Invalid mode "+mode);clear(p);}System.out.println("FIGHT_CAVES_DUPLICATE_START_PENDING_LEAVE_ACTIVE_EXIT_DEATH_RESPAWN_INVALID_MODES_AND_UNEARNED_REWARD_GUARDS_PASS");}
 static void resume(){Player p=actor();p.getFightCave().create(3);tick(p,16);kill(p,living(p).get(0));ok(p.waveId==1,"Checkpoint wave");ok(PlayerSave.saveGameInstant(p),"Checkpoint save");p.getFightCave().suspend();p.setDisconnected(true);Player q=actor();ok(PlayerSave.loadGame(q,"fight64qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.waveId==1&&q.fightCavesWaveType==3,"Checkpoint reload");PlayerHandler.players[1]=null;q.setIndex(2);PlayerHandler.players[2]=q;q.heightLevel=8;BossesPlayableCheck.applied(q);q.teleTimer=0;q.getFightCave().spawn();q.getFightCave().spawn();tick(q,16);ok(living(q).size()==2&&living(q).stream().allMatch(n->n.heightLevel==8),"Resume duplicated/wrong index height");clear(p);clear(q);System.out.println("FIGHT_CAVES_COMPLETED_WAVE_CHECKPOINT_REAL_SAVE_RELOAD_NEW_PLAYER_SLOT_HEIGHT_AND_SINGLE_RESUMED_WAVE_PASS");}
 static void prayers(){Player p=actor();BossRoutesCheck.at(p,2400,5087,4);p.teleTimer=0;NPC jad=NPCSpawning.spawnNpcOld(p,3127,2405,5087,4,0,255,97,500,500,false,false);jad.oldIndex=1;CombatType[] types={CombatType.MAGE,CombatType.RANGE,CombatType.MELEE};int[] prayers={16,17,18};for(int i=0;i<3;i++){jad.setAttackType(types[i]);Arrays.fill(p.prayerActive,false);p.prayerActive[prayers[i]]=true;int hp=p.getHealth().getCurrentHealth();for(int k=0;k<15;k++)NPCHitPlayer.applyDamage(jad,Server.npcHandler);ok(p.getHealth().getCurrentHealth()==hp,"Jad protection failed "+types[i]);Arrays.fill(p.prayerActive,false);for(int k=0;k<40&&p.getHealth().getCurrentHealth()==hp;k++)NPCHitPlayer.applyDamage(jad,Server.npcHandler);ok(p.getHealth().getCurrentHealth()<hp,"Jad unprotected no damage "+types[i]);}jad.unregisterInstant();clear(p);System.out.println("FIGHT_CAVES_JAD_MAGIC_RANGED_MELEE_NATIVE_DAMAGE_AND_THREE_CORRECT_PROTECTION_PRAYERS_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;complete(1);complete(2);complete(3);lifecycle();resume();prayers();fullInventory();groundSafety();System.out.println("FIGHT_CAVES_JAD_PLAYABLE_V64_PASS");System.exit(0);}
}
